def parse_pairs(s):
    pairs = {}
    key = ""
    value = ""
    in_quote = False
    for c in s + ";":  # 处理最后一个条目
        if c == ";":
            if key:
                if in_quote:
                    value = value.strip()
                pairs[key.strip()] = value
                key = ""
                value = ""
                in_quote = False
        elif c == "'":
            in_quote = not in_quote
        elif in_quote:
            value += c
        elif c == "=":
            if key:
                value = value.strip()
                pairs[key.strip()] = value
                key = ""
                value = ""
        elif key == "":
            key += c
        else:
            value += c
    return pairs
