class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.records = {}

    def hit(self, key, now):
        if key not in self.records:
            self.records[key] = {}
        record = self.records[key]
        timestamp = now - self.window
        count = 0
        for t in sorted(record.keys()):
            if t < timestamp:
                del record[t]
            else:
                count += 1
                if count == self.limit:
                    return False
        record[now] = 1
        return True

    def count(self, key, now):
        if key not in self.records:
            return 0
        record = self.records[key]
        timestamp = now - self.window
        count = 0
        for t in sorted(record.keys()):
            if t < timestamp:
                continue
            count += record[t]
        return count
